import{z as A,x as s,o as t,c as p,q as B,j as n,D as e,d as r,s as o,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"Melitz 异质企业","description":"","frontmatter":{"title":"Melitz 异质企业","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/melitz-heterogeneous-firms.md","filePath":"econ/melitz-heterogeneous-firms.md","lastUpdated":1791413859000}'),d={name:"econ/melitz-heterogeneous-firms.md"};function m(u,E,h,C,D,f){const i=s("Mermaid");return t(),p("div",null,[E[2]||(E[2]=B('<h1 id="melitz-异质企业" tabindex="-1">Melitz 异质企业 <a class="header-anchor" href="#melitz-异质企业" aria-label="Permalink to &quot;Melitz 异质企业&quot;">​</a></h1><div class="epigraph"><p>固定出口成本面前，只有生产率够高的企业出口；贸易自由化让资源从低生产率企业流向高生产率企业，行业平均生产率上升——这是选择，不只是每家规模变大。</p><footer>—— Melitz, The Impact of Trade on Intra-Industry Reallocations and Aggregate Industry Productivity, Econometrica 2003</footer></div><p><a href="/econ/krugman-new-trade">上一课</a>在对称企业下给出产业内贸易。本课缺口是现场最硬的事实：出口企业更大、更高效，多数企业不出口。Melitz 把生产率异质与出口固定成本写进同一套 CES。引力下一课把双边流量加总；本课先钉企业选择。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>企业抽到生产率 \\(\\varphi\\)，支付固定生产成本。出口另付固定成本 \\(f_x\\) 与冰山 \\(\\tau\\)。只有 \\(\\varphi\\ge\\varphi_x^*\\gt \\varphi^*\\)（国内存活门槛）的企业出口。开放：出口机会提高利润预期，进入增加，国内门槛 \\(\\varphi^*\\) 上升，最低效企业退出。行业加总生产率升。缺口不是再讲 Krugman 品种，而是：贸易的增益有一块来自<strong>组内再配置</strong>，即使没有 HO 的要素再配置。这与<a href="/econ/production-function-estimation">生产函数</a>估到的厂级 \\(\\omega\\) 分布对接：Melitz 把分布的截断当成一般均衡结果。</p><p><span class="marginnote">Melitz–Ottaviano、Bernard–Eaton–Jensen–Kortum 是变体。本课以 2003 年 CES + 帕累托（常用闭式）为最小模型。异质是生产率，不是任意固定效应。</span></p><p><span class="marginnote">「冰山成本」是说运费按比例「融化」货物本身：\\(\\tau=1.25\\) 意思是运 100 件只有 80 件抵达，多出的 25% 在路上蒸发。它把运输成本写成价格加成，省掉单独的运输行业，代价是所有货物按同一比例融化——黄金和砖头运费一样贵，显然不真实，但方便建模。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自由进入：期望利润（含退出）等于进入沉没成本。两个门槛由零利润与出口零利润定。贸易成本 \\(\\tau\\) 或 \\(f_x\\) 下降：\\(\\varphi_x^*\\) 降（更多企业出口），\\(\\varphi^*\\) 升（国内更卷）。福利：品种、加成（在某些变体）、再配置。对称国家仍可有产业内贸易，但只有一部分企业参与。</p>',9)),(t(),n(l,null,{default:e(()=>[o(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHI%5B%22%E7%94%9F%E4%BA%A7%E7%8E%87%20%CF%86%22%5D%20--%3E%20DOM%5B%22%CF%86%20%E2%89%A5%20%CF%86*%3A%20%E5%9B%BD%E5%86%85%E7%94%9F%E4%BA%A7%22%5D%0A%20%20PHI%20--%3E%20EXP%5B%22%CF%86%20%E2%89%A5%20%CF%86_x*%3A%20%E5%87%BA%E5%8F%A3%22%5D%0A%20%20LIB%5B%22%CF%84%20%E6%88%96%20f_x%20%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20EXIT%5B%22%E4%BD%8E%20%CF%86%20%E9%80%80%E5%87%BA%22%5D%0A%20%20LIB%20--%3E%20MORE%5B%22%E6%9B%B4%E5%A4%9A%E5%87%BA%E5%8F%A3%E4%BC%81%E4%B8%9A%22%5D%0A%20%20EXIT%20--%3E%20TFP%5B%22%E8%A1%8C%E4%B8%9A%E5%B9%B3%E5%9D%87%20%CF%86%20%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"与计量：出口固定成本的证据来自稀疏的出口参与、一次出口后的持续。因果设计可以估「关税下降对出口参与」，结构把参与收成 \\(\\varphi_x^*\\)。两条路，本课是结构机制。",-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"出口固定成本可以想象成海外展会的摊位费：不管卖出多少，先交一笔钱。利润薄的小厂付不起，利润厚的大厂当门票钱。这就是为什么「出不出口」是 0-1 的离散选择，而不是「多出口一点」的连续微调。")],-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,"机制是选择。固定成本使出口成为离散决策，不是每个 Krugman 企业都出一点。贸易自由化提高竞争（进口品种）同时打开外国市场：对高 \\(\\varphi\\) 是机会，对低 \\(\\varphi\\) 是淘汰。加总 TFP 升可以与部分企业死亡、部分地区劳动市场阵痛同时发生——后课 China shock 的微观基础之一，但 China shock 还有 HO/SS 的行业维度，不要把 Melitz 当成唯一通道。",-1)),E[7]||(E[7]=a("p",null,"与 HO：Melitz 通常一种劳动，分配冲突弱；把技能或地区流动摩擦叠进去，再配置的输家出现在企业与地区层，而不是 \\(w\\) 对 \\(r\\)。",-1)),E[8]||(E[8]=a("p",null,[a("span",{class:"marginnote"},"帕累托形状参数同时管企业规模分布与贸易弹性，这是方便也是识别风险：宏观贸易弹性与微观销售分布被同一参数锁死。后课 Eaton–Kortum 用另一套极端值。")],-1)),(t(),n(l,null,{default:e(()=>[o(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIB%5B%22%E8%B4%B8%E6%98%93%E8%87%AA%E7%94%B1%E5%8C%96%20%CF%84%20%E6%88%96%20f_x%20%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20COMP%5B%22%E8%BF%9B%E5%8F%A3%E5%93%81%E7%A7%8D%E5%A2%9E%E5%8A%A0%EF%BC%9A%E5%9B%BD%E5%86%85%E7%AB%9E%E4%BA%89%E5%8A%A0%E5%89%A7%22%5D%0A%20%20LIB%20--%3E%20OPP%5B%22%E5%A4%96%E5%9B%BD%E5%B8%82%E5%9C%BA%E6%89%93%E5%BC%80%EF%BC%9A%E5%87%BA%E5%8F%A3%E6%9C%BA%E4%BC%9A%22%5D%0A%20%20COMP%20--%3E%20LOW%5B%22%E4%BD%8E%20%CF%86%20%E4%BC%81%E4%B8%9A%EF%BC%9A%E5%88%A9%E6%B6%A6%E8%A2%AB%E5%8E%8B%E8%96%84%22%5D%0A%20%20OPP%20--%3E%20HIGH%5B%22%E9%AB%98%20%CF%86%20%E4%BC%81%E4%B8%9A%EF%BC%9A%E6%B5%B7%E5%A4%96%E5%88%A9%E6%B6%A6%E5%85%A5%E5%9C%BA%22%5D%0A%20%20LOW%20--%3E%20EXIT%5B%22%E9%80%80%E5%87%BA%E5%B9%B6%E9%87%8A%E6%94%BE%E5%8A%B3%E5%8A%A8%E4%B8%8E%E6%94%AF%E5%87%BA%22%5D%0A%20%20HIGH%20--%3E%20GROW%5B%22%E6%89%A9%E5%BC%A0%E5%B9%B6%E9%9B%87%E8%B5%B0%E9%87%8A%E6%94%BE%E7%9A%84%E8%B5%84%E6%BA%90%22%5D%0A%20%20EXIT%20--%3E%20RE%5B%22%E6%94%AF%E5%87%BA%E4%BB%BD%E9%A2%9D%E5%90%91%E9%AB%98%20%CF%86%20%E4%BC%81%E4%B8%9A%E5%86%8D%E9%85%8D%E7%BD%AE%22%5D%0A%20%20GROW%20--%3E%20RE%0A%20%20RE%20--%3E%20AGG%5B%22%E8%A1%8C%E4%B8%9A%E5%B9%B3%E5%9D%87%E7%94%9F%E4%BA%A7%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[9]||(E[9]=B('<p><span class="marginnote">初学者容易以为自由化让每家幸存企业都变大。Melitz 的机制里，收益盘子被更多出口企业分食，国内门槛抬高，一部分企业干脆消失；加总生产率上升主要来自「谁活着、资源归谁」的变化，而不是「每家都变强」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估企业级 \\(\\varphi\\) 的新分布。不把多产品企业、质量、网络全部展开。全球价值链后课把「出口」拆成任务。引力把 Melitz 加总成双边方程，下一课。不要用「异质企业」取消李嘉图：技术差仍可写在 \\(\\varphi\\) 的分布国别位置上。</p><p>后课默认：只有高 \\(\\varphi\\) 出口；自由化提高国内门槛、提高加总生产率。对称 Krugman 是 \\(\\varphi\\) 退化的特例。再配置增益与地区劳动市场损失可以并存。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>出口固定成本 ⇒ 选择：高生产率企业出口。</li><li>自由化：低 \\(\\varphi\\) 退出，行业平均生产率升。</li><li>产业内贸易与「多数企业不出口」同时成立。</li><li>加总 TFP 通道不同于 HO 的要素再配置。</li><li>出处：Melitz, <em>Econometrica</em> 2003。</li></ul>',6))])}const c=A(d,[["render",m]]);export{g as __pageData,c as default};
